import java.util.Scanner;

public class Main {
    static long N, K;
    static final long MOD = 1000000007;
    static long[] Power = new long[65];
    static long[][] Res = new long[35][35];
    static long[][][][][] S = new long[65][35][35][35];
    static long[][][][][] A = new long[65][35][35][35];
    static long[][][][][] P = new long[65][35][35][35];
    static long[][] Aux = new long[35][35];
    static Pair[] X = new Pair[105];

    static class Pair {
        long first, second;
        Pair(long f, long s) {
            first = f;
            second = s;
        }
    }

    static void copyArrays(long[][] dest, long[][] src, long size) {
        for (int i = 0; i < size; i++)
            for (int j = 0; j < size; j++)
                dest[i][j] = src[i][j];
    }

    static void addModulo(long[] x, long y) {
        for (int i = 0; i < y; i++) {
            x[i] += y;
            if (x[i] >= MOD) x[i] -= MOD;
        }
    }

    static void matrixMultiplyAlt(long[][] A, long[][] B, long[][] C, int n, int m, int p) {
        for (int i = 0; i < n; i++)
            for (int j = 0; j < p; j++) {
                C[i][j] = 0;
                for (int k = 0; k < m; k++)
                    C[i][j] = (C[i][j] + (A[i][k] * B[k][j]) % MOD) % MOD;
            }
    }

    static void setupA() {
        for (int x = 0; x < K; x++) {
            for (int i = 0; i < K + 1; i++) A[0][x][i][i] = 1;
            for (int j = 0; j < K + 1; j++) A[0][x][j][x] = 1;
        }
        copyArrays(P[0][0], A[0][0], K + 1);
        copyArrays(S[0][K - 1], A[0][K - 1], K + 1);
        for (int x = 1; x < K; x++)
            matrixMultiplyAlt(P[0][x - 1], A[0][x], P[0][x], K + 1, K + 1, K + 1);
        for (int x = K - 2; x >= 0; x--)
            matrixMultiplyAlt(A[0][x], S[0][x + 1], S[0][x], K + 1, K + 1, K + 1);
        int count = 1;
        for (long m = K; m <= N; m *= K, count++) {
            for (int x = 0; x < K; x++) {
                if (x > 0) {
                    copyArrays(A[count][x], S[count - 1][x], K + 1);
                    long[][] AuxTemp = new long[K + 1][K + 1];
                    matrixMultiplyAlt(A[count][x], P[count - 1][x - 1], AuxTemp, K + 1, K + 1, K + 1);
                    System.arraycopy(AuxTemp, 0, Aux, 0, Aux.length);
                    copyArrays(A[count][x], Aux, K + 1);
                } else {
                    copyArrays(A[count][x], S[count - 1][x], K + 1);
                }
            }
            copyArrays(P[count][0], A[count][0], K + 1);
            copyArrays(S[count][K - 1], A[count][K - 1], K + 1);
            for (int x = 1; x < K; x++)
                matrixMultiplyAlt(P[count][x - 1], A[count][x], P[count][x], K + 1, K + 1, K + 1);
            for (int x = K - 2; x >= 0; x--)
                matrixMultiplyAlt(A[count][x], S[count][x + 1], S[count][x], K + 1, K + 1, K + 1);
            if (m > N / K) break;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextLong();
        K = sc.nextLong();

        Power[0] = 1;
        int i = 1;
        while (Power[i - 1] <= N / K) {
            Power[i] = Power[i - 1] * K;
            i++;
        }
        int ind = i - 1;

        setupA();

        long init = N;
        long last = -1;
        long count = -1;
        int ind2 = 0;

        for (int iIdx = 0; iIdx <= K; iIdx++) {
            Res[0][iIdx] = 0;
        }
        Res[0][K] = 1;

        for (int iIdx = ind; iIdx >= 0; iIdx--) {
            while (Power[iIdx] <= init) {
                long[][] AuxTemp = new long[K + 1][K + 1];
                matrixMultiplyAlt(Res, A[iIdx][ind2], AuxTemp, K + 1, K + 1, K + 1);
                System.arraycopy(AuxTemp, 0, Res, 0, Res.length);
                ind2++;
                if (ind2 == K) ind2 = 0;
                init -= Power[iIdx];
            }
        }

        long ans = 0;
        for (int iIdx = 0; iIdx <= K; iIdx++) {
            ans = (ans + Res[0][iIdx]) % MOD;
        }
        System.out.println(ans);
        sc.close();
    }
}

